from xml.dom import minidom

dom = minidom.parse('unpacked/word/document.xml')
ns = {'w': 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}

def local(elem):
    return elem.tagName.split(':')[-1]

body = dom.getElementsByTagName('w:body')[0]
paras = [n for n in body.childNodes if n.nodeType == n.ELEMENT_NODE and local(n) == 'p']
print("Total paragraphs:", len(paras))
for idx, p in enumerate(paras):
    # get text
    texts = []
    for t in p.getElementsByTagName('w:t'):
        texts.append(''.join(ch.nodeValue or '' for ch in t.childNodes))
    full_text = ''.join(texts)
    # get runs and their rPr summary
    runs = [n for n in p.childNodes if n.nodeType == n.ELEMENT_NODE and local(n) == 'r']
    rpr_info = []
    for r in runs:
        rpr = [n for n in r.childNodes if n.nodeType == n.ELEMENT_NODE and local(n) == 'rPr']
        props = []
        if rpr:
            for c in rpr[0].childNodes:
                if c.nodeType == c.ELEMENT_NODE:
                    tag = local(c)
                    if tag == 'rFonts':
                        props.append('font=' + (c.getAttribute('w:ascii') or ''))
                    elif tag == 'sz':
                        props.append('sz=' + c.getAttribute('w:val'))
                    elif tag == 'b':
                        props.append('b')
                    elif tag == 'u':
                        props.append('u:' + c.getAttribute('w:val'))
                    elif tag == 'i':
                        props.append('i')
                    else:
                        props.append(tag)
        rpr_info.append(','.join(props))
    print(f"\n--- P{idx} (runs={len(runs)}) ---")
    print("text:", repr(full_text[:120]))
    for j, info in enumerate(rpr_info):
        print(f"  run{j} props: {info}")
