import sys
sys.path.insert(0, '.codex/skills/docx')
from scripts.utilities import XMLEditor

editor = XMLEditor('unpacked/word/document.xml')
dom = editor.dom

def para_text(p):
    parts = []
    for t in p.getElementsByTagName('w:t'):
        for node in t.childNodes:
            if node.nodeType == node.TEXT_NODE:
                parts.append(node.data)
    return ''.join(parts)

def is_headline(text):
    t = text.strip()
    if not t:
        return False
    if len(t) > 60:
        return False
    if not any(c.isalpha() for c in t):
        return False
    return all(c.isupper() or not c.isalpha() for c in t)

cands = []
for p in dom.getElementsByTagName('w:p'):
    text = para_text(p)
    if text.strip() and is_headline(text):
        cands.append(text)

print("Detected headline candidates (%d):" % len(cands))
for c in cands:
    print(" -", repr(c))
